INSERT INTO ontology (id, name, uri, description, position, license, license_url, retrieved, source_format, source_url, value_types) VALUES
  ('idta-02099-1', 'IDTA 02099-1 Digital Product Passport, Part 1', 'https://github.com/admin-shell-io/submodel-templates/blob/5285185b1ef9425fe45068bcbda8faaf74f3eb89/published/Digital%20Product%20Passport/Digital%20Product%20Passport%20Part-1/1/0/2/IDTA%2002099-1_Template%20Digital%20Product%20Passport%20-%20Part%201.json', 'Submodel template for the Asset Administration Shell, version 1.0.2, shown here as extracted elements. Digital record of product characteristics throughout its life cycle. SOURCE: FprEN 18223:2026(en)', '7', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', '2026-11-05', 'AAS JSON', 'https://raw.githubusercontent.com/admin-shell-io/submodel-templates/5285185b1ef9425fe45068bcbda8faaf74f3eb89/published/Digital%20Product%20Passport/Digital%20Product%20Passport%20Part-1/1/0/2/IDTA%2002099-1_Template%20Digital%20Product%20Passport%20-%20Part%201.json', 'xs:string, xs:dateTime'),
  ('idta-02006', 'IDTA 02006 Digital Nameplate', 'https://github.com/admin-shell-io/submodel-templates/blob/5285185b1ef9425fe45068bcbda8faaf74f3eb89/published/Digital%20nameplate/3/0/3/IDTA%2002006-3-0-3_Template_Digital%20Nameplate.json', 'Submodel template for the Asset Administration Shell, version 3.0.3, shown here as extracted elements. Contains the nameplate information attached to the product', '8', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', '2026-11-05', 'AAS JSON', 'https://raw.githubusercontent.com/admin-shell-io/submodel-templates/5285185b1ef9425fe45068bcbda8faaf74f3eb89/published/Digital%20nameplate/3/0/3/IDTA%2002006-3-0-3_Template_Digital%20Nameplate.json', 'xs:string, xs:date, xs:anyURI'),
  ('idta-02023', 'IDTA 02023 Carbon Footprint', 'https://github.com/admin-shell-io/submodel-templates/blob/5285185b1ef9425fe45068bcbda8faaf74f3eb89/published/Carbon%20Footprint/1/0/3/IDTA%2002023-1-0-3%20_Template_CarbonFootprint.json', 'Submodel template for the Asset Administration Shell, version 1.0.3, shown here as extracted elements. The Submodel provides the means to access the Carbon Footprint of the asset.', '9', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', '2026-11-05', 'AAS JSON', 'https://raw.githubusercontent.com/admin-shell-io/submodel-templates/5285185b1ef9425fe45068bcbda8faaf74f3eb89/published/Carbon%20Footprint/1/0/3/IDTA%2002023-1-0-3%20_Template_CarbonFootprint.json', 'xs:string, xs:dateTime, xs:anyURI, xs:decimal, xs:double'),
  ('idta-02003', 'IDTA 02003 Technical Data', 'https://github.com/admin-shell-io/submodel-templates/blob/5285185b1ef9425fe45068bcbda8faaf74f3eb89/published/Technical_Data/2/0/4/IDTA%2002003_2-0-4_Template_TechnicalData.json', 'Submodel template for the Asset Administration Shell, version 2.0.4, shown here as extracted elements. Submodel containing technical data of the asset and associated product classificatons', '10', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', '2026-11-05', 'AAS JSON', 'https://raw.githubusercontent.com/admin-shell-io/submodel-templates/5285185b1ef9425fe45068bcbda8faaf74f3eb89/published/Technical_Data/2/0/4/IDTA%2002003_2-0-4_Template_TechnicalData.json', 'xs:string, xs:date'),
  ('idta-02004', 'IDTA 02004 Handover Documentation', 'https://github.com/admin-shell-io/submodel-templates/blob/5285185b1ef9425fe45068bcbda8faaf74f3eb89/published/Handover%20Documentation/2/0/4/IDTA%2002004-2-0-4_Template_HandoverDocumentation.json', 'Submodel template for the Asset Administration Shell, version 2.0.4, shown here as extracted elements. The Submodel defines a set meta data for the handover of documentation from the manufacturer to the operator for industrial equipment', '11', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', '2026-11-05', 'AAS JSON', 'https://raw.githubusercontent.com/admin-shell-io/submodel-templates/5285185b1ef9425fe45068bcbda8faaf74f3eb89/published/Handover%20Documentation/2/0/4/IDTA%2002004-2-0-4_Template_HandoverDocumentation.json', 'xs:string, xs:boolean, xs:date'),
  ('idta-02002', 'IDTA 02002 Contact Information', 'https://github.com/admin-shell-io/submodel-templates/blob/5285185b1ef9425fe45068bcbda8faaf74f3eb89/published/Contact%20Information/1/0/4/IDTA%2002002-1-0-4_Template_ContactInformation.json', 'Submodel template for the Asset Administration Shell, version 1.0.4, shown here as extracted elements. The Submodel “ContactInformations” is the collection for various contact information.', '12', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', '2026-11-05', 'AAS JSON', 'https://raw.githubusercontent.com/admin-shell-io/submodel-templates/5285185b1ef9425fe45068bcbda8faaf74f3eb89/published/Contact%20Information/1/0/4/IDTA%2002002-1-0-4_Template_ContactInformation.json', 'xs:string'),
  ('idta-02011', 'IDTA 02011 Hierarchical Structures enabling Bills of Material', 'https://github.com/admin-shell-io/submodel-templates/blob/5285185b1ef9425fe45068bcbda8faaf74f3eb89/published/Hierarchical%20Structures%20enabling%20Bills%20of%20Material/1/1/4/IDTA%2002011-1-1-4_Template_HSEBoM.json', 'Submodel template for the Asset Administration Shell, version 1.1.4, shown here as extracted elements. The Submodel HierarchicalStructures identified by its semanticId. The Submodel idShort can be picked freely.', '13', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', '2026-11-05', 'AAS JSON', 'https://raw.githubusercontent.com/admin-shell-io/submodel-templates/5285185b1ef9425fe45068bcbda8faaf74f3eb89/published/Hierarchical%20Structures%20enabling%20Bills%20of%20Material/1/1/4/IDTA%2002011-1-1-4_Template_HSEBoM.json', 'xs:string, xs:unsignedLong'),
  ('idta-02080', 'IDTA 02080 Material Data for Plastic Waste', 'https://github.com/admin-shell-io/submodel-templates/blob/5285185b1ef9425fe45068bcbda8faaf74f3eb89/published/Material%20Data%20for%20Plastic%20Waste/1/0/2/IDTA_02080_Template_Material%20Data%20for%20Plastic%20Waste.json', 'Submodel template for the Asset Administration Shell, version 1.0.2, shown here as extracted elements. Submodel template for material data enabling classification of plastics according to EN 18065', '14', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', '2026-11-05', 'AAS JSON', 'https://raw.githubusercontent.com/admin-shell-io/submodel-templates/5285185b1ef9425fe45068bcbda8faaf74f3eb89/published/Material%20Data%20for%20Plastic%20Waste/1/0/2/IDTA_02080_Template_Material%20Data%20for%20Plastic%20Waste.json', 'xs:string, xs:float, xs:decimal');
INSERT INTO ontology_term (id, ontology_id, label, uri, definition, position, kind, value_type) VALUES
  ('idta-02099-1:uniqueProductIdentifier', 'idta-02099-1', 'unique product identifier', 'https://admin-shell.io/idta/cds/uniqueProductIdentifier/1', 'Unique string of characters for the identification of a product, that also enables a web link to the digital product passport. String formatted according to FprEN 18219:2026. SOURCE: EN 18223:2026(en)', '44', 'Property', 'xs:string'),
  ('idta-02003:ProductClassifications/ProductClassification', 'idta-02003', 'Product classification', '0173-1#02-ABK162#002/0173-1#01-AHX839#002', 'Single product classification item by association with product class in a particular classification system or property dictionary', '45', 'SubmodelElementCollection', NULL),
  ('idta-02006:ManufacturerName', 'idta-02006', 'ManufacturerName', '0112/2///61987#ABA565#009', 'legally valid designation of the natural or judicial person which is directly responsible for the design, production, packaging and labeling of a product in respect to its being brought into circulation', '46', 'MultiLanguageProperty', NULL),
  ('idta-02002:ContactInformation', 'idta-02002', 'ContactInformation', 'https://admin-shell.io/zvei/nameplate/1/0/ContactInformations/ContactInformation', 'The SMC “ContactInformation” contains information on how to contact the manufacturer or an authorised service provider, e.g. when a maintenance service is required', '47', 'SubmodelElementCollection', NULL),
  ('idta-02099-1:economicOperatorId', 'idta-02099-1', 'economic operator ID', 'https://admin-shell.io/idta/cds/economicOperatorId/1', 'Unique string of characters for the identification of an actor involved in a product''s life cycle. String formatted according to FprEN 18219:2026. SOURCE: EN 18223:2026(en)', '48', 'Property', 'xs:string'),
  ('idta-02080:InformationCharacteristics', 'idta-02080', 'InformationCharacteristics', 'https://admin-shell.io/idta/en18065materialdata/InformationCharacteristics/1/0', 'Group of informational characteristics that identify and classify the plastic waste material (e.g. polymer type, formulation, origin-related data) according to EN 18065', '49', 'SubmodelElementCollection', NULL),
  ('idta-02080:InformationCharacteristics/PresenceOfModifyingAdditives', 'idta-02080', 'PresenceOfModifyingAdditives', 'https://admin-shell.io/idta/en18065materialdata/PresenceOfModifyingAdditives/1/0', 'Stabilizers, plasticizers, flame retardants, etc.', '50', 'SubmodelElementList', NULL),
  ('idta-02023:ProductCarbonFootprints', 'idta-02023', 'Product carbon footprint', 'https://admin-shell.io/idta/CarbonFootprint/ProductCarbonFootprints/1/0', 'Balance of greenhouse gas emissions along the entire life cycle of a product in a defined application and in relation to a defined unit of use', '51', 'SubmodelElementList', NULL),
  ('idta-02011:EntryNode/HasPart', 'idta-02011', 'HasPart', 'https://admin-shell.io/idta/HierarchicalStructures/HasPart/1/0', 'Modeling of logical connections between components and sub-components. Either this or "IsPartOf" must be used, not both.', '52', 'RelationshipElement', NULL),
  ('idta-02080:InformationCharacteristics/RecycledContent', 'idta-02080', 'RecycledContent', 'https://admin-shell.io/idta/en18065materialdata/RecycledContent/1/0', 'Percentage by weight of recycled plastic in the material as calculated according to Section 5.1 of EN 18065', '53', 'Property', 'xs:decimal'),
  ('idta-02006:CountryOfOrigin', 'idta-02006', 'CountryOfOrigin', '0112/2///61987#ABP462#001', 'country where the product was manufactured', '54', 'Property', 'xs:string'),
  ('idta-02099-1:facilityId', 'idta-02099-1', 'facility ID', 'https://admin-shell.io/idta/cds/facilityId/1', 'Unique string of characters for the identification of locations or buildings involved in a product''s value chain or used by actors involved in a product''s life cycle. String formatted according to EN 18219:2026. SOURCE: EN 18223:2026(en)', '55', 'Property', 'xs:string'),
  ('idta-02080:InformationCharacteristics/ChainOfCustody', 'idta-02080', 'ChainOfCustody', 'https://admin-shell.io/idta/en18065materialdata/ChainOfCustody/1/0', 'Physical segregation, controlled blending, mass balance etc. (with indication, which attribution model has been used pursuant to European or international standard)', '56', 'SubmodelElementCollection', NULL),
  ('idta-02006:AssetSpecificProperties/GuidelineSpecificProperties/item1/GuidelineForConformityDeclaration', 'idta-02006', 'GuidelineForConformityDeclaration', '0173-1#02-AAO856#002', 'guideline, stipulation or legislation used for determining conformity', '57', 'Property', 'xs:string'),
  ('idta-02006:Markings/Marking/DesignationOfCertificateOrApproval', 'idta-02006', 'DesignationOfCertificateOrApproval', '0112/2///61987#ABH783#003', 'alphanumeric character sequence identifying a certificate or approval', '58', 'Property', 'xs:string'),
  ('idta-02080:InformationCharacteristics/CertificateOfAnalysis', 'idta-02080', 'CertificateOfAnalysis', 'https://admin-shell.io/idta/en18065materialdata/CertificateOfAnalysis/1/0', 'Reference to certificate of analysis according to EN 10204:2005, clause 3.1', '59', 'SubmodelElementCollection', NULL),
  ('idta-02003:TechnicalPropertyAreas', 'idta-02003', 'Technical property areas', '0173-1#02-ABK163#002', 'List of all technical property areas', '60', 'SubmodelElementList', NULL),
  ('idta-02080:PropertyCharacteristics', 'idta-02080', 'PropertyCharacteristics', 'https://admin-shell.io/idta/en18065materialdata/PropertyCharacteristics/1/0', 'Group of physical and chemical property characteristics of the plastic waste material (e.g. viscosity, density, mechanical values) as specified in EN 18065', '61', 'SubmodelElementCollection', NULL),
  ('idta-02099-1:submodel', 'idta-02099-1', 'Digital Product Passport (DPP)', 'https://admin-shell.io/idta/cds/dppMetadata/1', 'Digital record of product characteristics throughout its life cycle. SOURCE: FprEN 18223:2026(en)', '62', 'Submodel', NULL),
  ('idta-02004:Documents/Document', 'idta-02004', 'Document (handover documentation)', '0173-1#02-ABI500#003/0173-1#01-AHF579#003', 'Each SubmodelElementCollection describes a document by standard, which is associated to the particular Asset Administration Shell', '63', 'SubmodelElementCollection', NULL),
  ('idta-02006:Markings/Marking', 'idta-02006', 'Marking', '0112/2///61360_7#AAS009#001', 'Single marking information', '64', 'SubmodelElementCollection', NULL);
INSERT INTO data_requirement_term (data_requirement_id, term_id, match, note) VALUES
  ('product-id', 'idta-02099-1:uniqueProductIdentifier', 'exact', NULL),
  ('commodity-code', 'idta-02003:ProductClassifications/ProductClassification', 'broad', 'A class in any classification system; the CN or HS code would be one such entry.'),
  ('manufacturer', 'idta-02006:ManufacturerName', 'close', 'The name.'),
  ('manufacturer', 'idta-02002:ContactInformation', 'close', 'The contact details; they can also be those of a service provider.'),
  ('importer', 'idta-02099-1:economicOperatorId', 'broad', 'Identifies any actor in the product''s life cycle, of which the importer is one.'),
  ('producer-registration', 'idta-02099-1:economicOperatorId', 'broad', 'An identifier for any actor; the acts mean a number in a national register of producers.'),
  ('supply-chain-operators', 'idta-02099-1:economicOperatorId', 'close', 'Identifies the actor, without naming its role in the chain.'),
  ('material-composition', 'idta-02080:InformationCharacteristics', 'narrow', 'Plastic waste material only, not a finished product''s full composition.'),
  ('substances-of-concern', 'idta-02080:InformationCharacteristics/PresenceOfModifyingAdditives', 'narrow', 'Additives in plastic material, by name and CAS number; ESPR sets its own legal definition of the wider class.'),
  ('carbon-footprint', 'idta-02023:ProductCarbonFootprints', 'close', 'Embedded emissions under CBAM have a narrower boundary.'),
  ('environmental-footprint', 'idta-02023:ProductCarbonFootprints', 'narrow', 'Greenhouse gases only, one indicator among the several a multi-indicator footprint reports.'),
  ('precursors', 'idta-02011:EntryNode/HasPart', 'broad', 'Links a product to its components; each input''s embedded emissions would sit in that component''s own carbon footprint submodel.'),
  ('recycled-content', 'idta-02080:InformationCharacteristics/RecycledContent', 'narrow', 'Recycled plastic only, as calculated under EN 18065.'),
  ('production-site', 'idta-02006:CountryOfOrigin', 'close', 'The country.'),
  ('production-site', 'idta-02099-1:facilityId', 'close', 'The site.'),
  ('chain-of-custody', 'idta-02080:InformationCharacteristics/ChainOfCustody', 'narrow', 'The attribution model for plastic waste material, not custody records along a whole supply chain.'),
  ('conformity', 'idta-02006:AssetSpecificProperties/GuidelineSpecificProperties/item1/GuidelineForConformityDeclaration', 'close', 'Names what conformity was determined against, not the declaration itself.'),
  ('verification', 'idta-02006:Markings/Marking/DesignationOfCertificateOrApproval', 'broad', 'Identifies a certificate or approval, whoever issued it; says nothing of third-party independence.'),
  ('verification', 'idta-02080:InformationCharacteristics/CertificateOfAnalysis', 'narrow', 'An inspection certificate for plastic waste material under EN 10204.'),
  ('performance', 'idta-02003:TechnicalPropertyAreas', 'broad', 'Holds any technical properties; the template leaves which ones to the product class.'),
  ('performance', 'idta-02080:PropertyCharacteristics', 'narrow', 'Measured properties of plastic waste material only.'),
  ('dpp', 'idta-02099-1:submodel', 'exact', NULL),
  ('instructions', 'idta-02004:Documents/Document', 'broad', 'Metadata for any handed-over document; instructions and safety information are classes of document.'),
  ('label', 'idta-02006:Markings/Marking', 'close', 'A marking such as CE and its symbol, not all the text a label must carry.');
INSERT INTO data_point (id, name, description, position, path, kind, value_type, cardinality, unit, semantic_id) VALUES
  ('idta-02099-1:digitalProductPassportId', 'unique product passport identifier (DPP ID)', 'Unique identifier of an instance of the digital product passport. SOURCE: EN 18223:2026(en)', '0', 'digitalProductPassportId', 'Property', 'xs:string', '1', NULL, 'https://admin-shell.io/idta/cds/digitalProductPassportId/1'),
  ('idta-02099-1:uniqueProductIdentifier', 'unique product identifier', 'Unique string of characters for the identification of a product, that also enables a web link to the digital product passport. String formatted according to FprEN 18219:2026. SOURCE: EN 18223:2026(en)', '1', 'uniqueProductIdentifier', 'Property', 'xs:string', '1', NULL, 'https://admin-shell.io/idta/cds/uniqueProductIdentifier/1'),
  ('idta-02099-1:granularity', 'granularity', 'The granularity of the Product. There are three values: ‘Model‘, ‘Item‘ and ‘Batch‘. The term ‘model‘ usually refers to a version of a product of which all units share the same technical characteristics relevant for the ecodesign requirements and the same model identifier, the term ‘batch‘ usually refers to a subset of a specific model composed of all products produced in a specific manufacturing plant at a specific moment in time and the term ‘item’ usually refers to a single unit of a model. SOURCE: ESPR p2024/1781, REGULATION (EU) 2024/1781 OF THE EUROPEAN PARLIAMENT AND OF THE COUNCIL of 13 June 2024 establishing a framework for the setting of ecodesign requirements for sustainable products, amending Directive (EU) 2020/1828 and Regulation (EU) 2023/1542 and repealing Directive 2009/125/EC. URI: OJ:L_202401781', '2', 'granularity', 'Property', 'xs:string', '1', NULL, 'https://admin-shell.io/idta/cds/granularity/1'),
  ('idta-02099-1:dppSchemaVersion', 'DPP schema version', 'Reference standard the DPP instance schema refers to. SOURCE: FprEN 18223:2026(en)', '3', 'dppSchemaVersion', 'Property', 'xs:string', '1', NULL, 'https://admin-shell.io/idta/cds/dppSchemaVersion/1'),
  ('idta-02099-1:dppStatus', 'DPP status', 'Status of the DPP instance as digital resource. SOURCE: EN 18223:2026(en)', '4', 'dppStatus', 'Property', 'xs:string', '1', NULL, 'https://admin-shell.io/idta/cds/dppStatus/1'),
  ('idta-02099-1:lastUpdate', 'last update', 'Date and time of the latest update to the DPP instance. String formatted as Timestamp UTC-based according to ISO 8601-1:2019/Amd1:2022. SOURCE: EN 18223:2026(en)', '5', 'lastUpdate', 'Property', 'xs:dateTime', '1', NULL, 'https://admin-shell.io/idta/cds/lastUpdate/1'),
  ('idta-02099-1:economicOperatorId', 'economic operator ID', 'Unique string of characters for the identification of an actor involved in a product''s life cycle. String formatted according to FprEN 18219:2026. SOURCE: EN 18223:2026(en)', '6', 'economicOperatorId', 'Property', 'xs:string', '1', NULL, 'https://admin-shell.io/idta/cds/economicOperatorId/1'),
  ('idta-02099-1:facilityId', 'facility ID', 'Unique string of characters for the identification of locations or buildings involved in a product''s value chain or used by actors involved in a product''s life cycle. String formatted according to EN 18219:2026. SOURCE: EN 18223:2026(en)', '7', 'facilityId', 'Property', 'xs:string', '0..1', NULL, 'https://admin-shell.io/idta/cds/facilityId/1'),
  ('idta-02099-1:contentSpecificationIds/contentSpecificationId', 'contentSpecificationId', 'Reference to horizontal or product-type related content specification for the DPP. SOURCE: EN 18223:2026(en)', '8', 'contentSpecificationIds/contentSpecificationId', 'Property', 'xs:string', '1..*', NULL, 'https://admin-shell.io/idta/cds/contentSpecificationId/1'),
  ('idta-02006:URIOfTheProduct', 'URIOfTheProduct', 'unique global identification of the product instance using an universal resource identifier (URI)', '9', 'URIOfTheProduct', 'Property', 'xs:anyURI', '1', NULL, '0112/2///61987#ABN590#002'),
  ('idta-02006:ManufacturerName', 'ManufacturerName', 'legally valid designation of the natural or judicial person which is directly responsible for the design, production, packaging and labeling of a product in respect to its being brought into circulation', '10', 'ManufacturerName', 'MultiLanguageProperty', NULL, '1', NULL, '0112/2///61987#ABA565#009'),
  ('idta-02006:ManufacturerProductDesignation', 'ManufacturerProductDesignation', 'short description of the product (short text), third or lowest level of a 3 level manufacturer specific product hierarchy', '11', 'ManufacturerProductDesignation', 'MultiLanguageProperty', NULL, '1', NULL, '0112/2///61987#ABA567#009'),
  ('idta-02006:AddressInformation', 'AddressInformation', 'Note: this set of information is defined by SMT drop-in "Address Information"', '12', 'AddressInformation', 'SubmodelElementCollection', NULL, '1', NULL, 'https://admin-shell.io/zvei/nameplate/1/0/ContactInformations/AddressInformation'),
  ('idta-02006:ManufacturerProductRoot', 'ManufacturerProductRoot', 'top level of a 3 level manufacturer specific product hierarchy', '13', 'ManufacturerProductRoot', 'MultiLanguageProperty', NULL, '0..1', NULL, '0112/2///61360_7#AAS011#001'),
  ('idta-02006:ManufacturerProductFamily', 'ManufacturerProductFamily', 'second level of a 3 level manufacturer specific product hierarchy', '14', 'ManufacturerProductFamily', 'MultiLanguageProperty', NULL, '0..1', NULL, '0112/2///61987#ABP464#002'),
  ('idta-02006:ManufacturerProductType', 'ManufacturerProductType', 'characteristic to differentiate between different products of a product family or special variants', '15', 'ManufacturerProductType', 'Property', 'xs:string', '0..1', NULL, '0112/2///61987#ABA300#008'),
  ('idta-02006:OrderCodeOfManufacturer', 'OrderCodeOfManufacturer', 'unique combination of numbers and letters issued by the manufacturer that is used to identify the device for ordering', '16', 'OrderCodeOfManufacturer', 'Property', 'xs:string', '1', NULL, '0112/2///61987#ABA950#008'),
  ('idta-02006:ProductArticleNumberOfManufacturer', 'ProductArticleNumberOfManufacturer', 'unique product identifier of the manufacturer', '17', 'ProductArticleNumberOfManufacturer', 'Property', 'xs:string', '0..1', NULL, '0112/2///61987#ABA581#007'),
  ('idta-02006:SerialNumber', 'SerialNumber', 'unique combination of numbers and letters used to identify the device once it has been manufactured', '18', 'SerialNumber', 'Property', 'xs:string', '0..1', NULL, '0112/2///61987#ABA951#009'),
  ('idta-02006:YearOfConstruction', 'YearOfConstruction', 'year in which the manufacturing process is completed', '19', 'YearOfConstruction', 'Property', 'xs:string', '0..1', NULL, '0112/2///61987#ABP000#002'),
  ('idta-02006:DateOfManufacture', 'DateOfManufacture', 'date when an item was manufactured', '20', 'DateOfManufacture', 'Property', 'xs:date', '0..1', NULL, '0112/2///61987#ABB757#007'),
  ('idta-02006:HardwareVersion', 'HardwareVersion', 'version of the hardware supplied with the device', '21', 'HardwareVersion', 'Property', 'xs:string', '0..1', NULL, '0112/2///61987#ABA926#008'),
  ('idta-02006:FirmwareVersion', 'FirmwareVersion', 'version of the firmware supplied with the device', '22', 'FirmwareVersion', 'Property', 'xs:string', '0..1', NULL, '0112/2///61987#ABA302#006'),
  ('idta-02006:SoftwareVersion', 'SoftwareVersion', 'version of the software used by the device', '23', 'SoftwareVersion', 'Property', 'xs:string', '0..1', NULL, '0112/2///61987#ABA601#008'),
  ('idta-02006:CountryOfOrigin', 'CountryOfOrigin', 'country where the product was manufactured', '24', 'CountryOfOrigin', 'Property', 'xs:string', '0..1', NULL, '0112/2///61987#ABP462#001'),
  ('idta-02006:UniqueFacilityIdentifier', 'UniqueFacilityIdentifier', 'unique string of characters for the identification of locations or buildings involved in a product’s value chain or used by actors involved in a product’s value chain', '25', 'UniqueFacilityIdentifier', 'Property', 'xs:string', '0..1', NULL, 'https://admin-shell.io/idta/nameplate/3/0/UniqueFacilityIdentifier'),
  ('idta-02006:CompanyLogo', 'CompanyLogo', 'a graphic mark used to represent a company, an organisation or a product', '26', 'CompanyLogo', 'File', NULL, '0..1', NULL, '0112/2///61987#ABP463#001'),
  ('idta-02006:Markings/Marking/MarkingName', 'MarkingName', 'common name of the marking', '27', 'Markings/Marking/MarkingName', 'Property', 'xs:string', '1', NULL, '0112/2///61987#ABA231#009'),
  ('idta-02006:Markings/Marking/DesignationOfCertificateOrApproval', 'DesignationOfCertificateOrApproval', 'alphanumeric character sequence identifying a certificate or approval', '28', 'Markings/Marking/DesignationOfCertificateOrApproval', 'Property', 'xs:string', '0..1', NULL, '0112/2///61987#ABH783#003'),
  ('idta-02006:Markings/Marking/IssueDate', 'IssueDate', 'date, at which the specified certificate is issued', '29', 'Markings/Marking/IssueDate', 'Property', 'xs:date', '0..1', NULL, '0112/2///61987#ABO097#001'),
